const D = { density:.55, scale:1, speed:1, energy:.6, hue:205, turb:.6, trail:.5, x:.5, y:.5, style:'silk', act:'flow', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const st = P.style, key = width+'x'+height;
const N = Math.floor(120 + P.density*380); // 120..500 particles
// seeded LCG so respawns stay deterministic (no p5 random -> no global pollution)
if (S.seedUsed !== P.seed || S.key !== key || !S.ps || S.ps.length !== N){
  S.seedUsed = P.seed; S.key = key;
  let z = (P.seed*2654435761 + 12345) >>> 0;
  S.rnd = () => { z = (z*1664525 + 1013904223) >>> 0; return z/4294967296; };
  S.noff = S.rnd()*1000;
  S.ps = [];
  for (let i=0;i<N;i++) S.ps.push({ x:S.rnd()*width, y:S.rnd()*height, px:0, py:0 });
}
const rnd = S.rnd;
const intn = (K.intensity!=null?K.intensity:0.6);
// act dramaturgy: steady flow / periodic gusts / laminar calm
let turbMul = 1, spdMul = 1;
if (P.act==='gust'){ turbMul = 1 + K.pulse*0.7 + (K.section%2?0.4:0); spdMul = 1 + K.pulse*0.6; }
else if (P.act==='calm'){ turbMul = 0.5; spdMul = 0.7; }
// continuous real-time field evolution via K.t (never re-phases)
const zt = K.t*(0.05 + P.speed*0.045) + S.noff;
const sc = 0.0022 / P.scale;
const turb = (0.8 + P.turb*2.4 + A.lowmid*1.8 + A.mid*1.2) * turbMul;
const spd = (0.9 + P.speed*1.4) * (0.7 + intn*0.6) * spdMul;
const hueDrift = K.t*4 + P.hue;
// style base tone / trail fade (gentle accumulation, not a flash)
noStroke(); blendMode(BLEND);
if (st==='ink') fill(34,9,90, 8+P.trail*9);
else if (st==='schematic') fill(218,72,13, 30);
else fill(230,48,4, 6+P.trail*8);
rect(0,0,width,height);
if (st==='schematic'){
  // field diagram: grid of rotating direction arrows (schematic / non-representational)
  const step = Math.max(u*0.05, u*(0.12 - P.density*0.06));
  stroke(192,62,94, 60); strokeWeight(1.1);
  for (let gx=step*0.5; gx<width; gx+=step){
    for (let gy=step*0.5; gy<height; gy+=step){
      const ang = noise(gx*sc, gy*sc, zt)*TWO_PI*turb;
      const len = step*0.42;
      const ex = gx+Math.cos(ang)*len, ey = gy+Math.sin(ang)*len;
      line(gx,gy,ex,ey);
      const ah = len*0.32;
      line(ex,ey, ex-Math.cos(ang-0.5)*ah, ey-Math.sin(ang-0.5)*ah);
